def pin(p):
    p=p.resolve();b=p.read_bytes()
    return dict(path=p.as_posix(),bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
before=[pin(ROOT/n) for n in SOURCES]
def new(p,content):
    p=p.resolve();assert p.is_relative_to(ROOT) and not p.exists()
    p.parent.mkdir(parents=True,exist_ok=True)
    raw=content.encode('utf-8');temp=p.with_name(p.name+'.tmp_'+datetime.now().strftime('%H%M%S_%f'))
    with temp.open('xb') as f:
        f.write(raw);f.flush();os.fsync(f.fileno())
    assert temp.read_bytes()==raw
    temp.rename(p);assert p.read_bytes()==raw
    created.append(pin(p))
